import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";
import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";
import CardFooter from "@marko-ui/shadcn/ui/card/footer.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

static const today = new Date(2026, 5, 15);

static function addDays(base: Date, days: number) {
  const result = new Date(base);
  result.setDate(result.getDate() + days);
  return { year: result.getFullYear(), month: result.getMonth() + 1, day: result.getDate() };
}

static const presets = [
  { label: "Today", days: 0 },
  { label: "Tomorrow", days: 1 },
  { label: "In 3 days", days: 3 },
  { label: "In a week", days: 7 },
  { label: "In 2 weeks", days: 14 },
];

<let/value=[addDays(today, 0)]/>

<Card class="mx-auto w-fit max-w-[300px]" size="sm">
  <CardContent>
    <Calendar
      value=value
      valueChange=(next) => { value = next; }
      class="p-0 [--cell-size:--spacing(9.5)]"
    />
  </CardContent>
  <CardFooter class="flex flex-wrap gap-2 border-t">
    <for|preset| of=presets>
      <Button type="button"
        variant="outline"
        size="sm"
        class="flex-1"
        onClick() {
          value = [addDays(today, preset.days)];
        }
      >
        ${preset.label}
      </Button>
    </for>
  </CardFooter>
</Card>

import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";
import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";

static const bookedStart = new Date(2026, 0, 12);

static function toPlain(date: Date) {
  return { year: date.getFullYear(), month: date.getMonth() + 1, day: date.getDate() };
}

static const bookedDates = Array.from({ length: 15 }, (_, i) => {
  const date = new Date(bookedStart);
  date.setDate(date.getDate() + i);
  return toPlain(date);
});

static function isBooked(candidate: { year: number; month: number; day: number }) {
  return bookedDates.some(
    (booked) => booked.year === candidate.year && booked.month === candidate.month && booked.day === candidate.day,
  );
}

static const focusedValue = toPlain(bookedStart);

<Card class="mx-auto w-fit p-0">
  <CardContent class="p-0">
    <Calendar
      isDateUnavailable=(date) => isBooked({ year: date.year, month: date.month, day: date.day })
      defaultFocusedValue=focusedValue
    />
  </CardContent>
</Card>

import Calendar from "@marko-ui/shadcn/ui/calendar/calendar.marko";
import Card from "@marko-ui/shadcn/ui/card/card.marko";
import CardContent from "@marko-ui/shadcn/ui/card/content.marko";

static const rangeStart = new Date(2026, 5, 8);

static function toPlain(date: Date) {
  return { year: date.getFullYear(), month: date.getMonth() + 1, day: date.getDate() };
}

static function addDays(base: Date, days: number) {
  const result = new Date(base);
  result.setDate(result.getDate() + days);
  return result;
}

<let/value=[toPlain(rangeStart), toPlain(addDays(rangeStart, 10))]/>

<Card class="mx-auto w-fit p-0">
  <CardContent class="p-0">
    <Calendar
      selectionMode="range"
      value=value
      valueChange=(next) => { value = next; }
      captionLayout="dropdown"
      class="[--cell-size:--spacing(10)] md:[--cell-size:--spacing(12)]"
    />
  </CardContent>
</Card>

